public static long findNthGoodInteger(long N) {
    long count = 0;
    long current = 0;

    while (true) {
        if (isGoodInteger(current)) {
            count++;
            if (count == N) {
                return current;
            }
        }
        current++;
    }
}

private static boolean isGoodInteger(long number) {
    while (number > 0) {
        long digit = number % 10;
        if (digit % 2 != 0) {
            return false;
        }
        number /= 10;
    }
    return true;
}
